import random
from datetime import datetime

import pandas as pd
import streamlit as st
from streamlit_autorefresh import st_autorefresh

from ui_theme import apply_theme

apply_theme()

st.title("Crew & environment")
st.caption("Shared spacecraft environmental monitoring · cabin-wide sensor readings.")

st.info(
    "SIMULATION MODE — readings are generated by software for demonstration. "
    "No physical sensors are connected."
)

ASTRONAUTS = {
    "Astronaut 1": "AST-001",
    "Astronaut 2": "AST-002",
}

def initial_crew_values(seed):
    random.seed(seed)
    return {
        "heart_rate_bpm": round(random.uniform(66, 74), 1),
        "sleep_hours": round(random.uniform(6.5, 8.5), 1),
        "activity_demo_index": random.randint(30, 55),
    }

st.session_state.setdefault("crew_readings", [])
st.session_state.setdefault("cosmo_sensor_running", False)
st.session_state.setdefault("cosmo_astronaut_values", {
    "AST-001": initial_crew_values(101),
    "AST-002": initial_crew_values(202),
})
st.session_state.setdefault("cosmo_environment_values", {
    "oxygen_percent": 20.9,
    "co2_ppm": 1100.0,
    "temperature_c": 22.0,
    "humidity_percent": 45.0,
    "pressure_kpa": 101.0,
})

control_left, control_right, control_info = st.columns([1, 1, 2])
with control_left:
    if st.button(
        "Stop simulation" if st.session_state.cosmo_sensor_running else "Start live simulation",
        type="primary",
        use_container_width=True,
    ):
        st.session_state.cosmo_sensor_running = not st.session_state.cosmo_sensor_running
        st.rerun()
with control_right:
    if st.button("Reset simulated readings", use_container_width=True):
        st.session_state.cosmo_sensor_running = False
        st.session_state.cosmo_astronaut_values = {
            "AST-001": initial_crew_values(101),
            "AST-002": initial_crew_values(202),
        }
        st.session_state.cosmo_environment_values = {
            "oxygen_percent": 20.9,
            "co2_ppm": 1100.0,
            "temperature_c": 22.0,
            "humidity_percent": 45.0,
            "pressure_kpa": 101.0,
        }
        st.session_state.crew_readings = []
        st.rerun()
with control_info:
    if st.session_state.cosmo_sensor_running:
        st.success("Simulation running · updating every 3 seconds")
    else:
        st.warning("Simulation paused · press Start live simulation")

def drift(value, amount, low, high, decimals=1):
    return round(max(low, min(high, value + random.uniform(-amount, amount))), decimals)

def generate_sensor_snapshot():
    timestamp = datetime.now().isoformat(timespec="seconds")

    # Each astronaut has independent wearable/physiological sensor readings.
    for astronaut_name, astronaut_id in ASTRONAUTS.items():
        crew = st.session_state.cosmo_astronaut_values[astronaut_id]
        crew["heart_rate_bpm"] = drift(crew["heart_rate_bpm"], 2.8, 52, 115, 1)
        crew["sleep_hours"] = drift(crew["sleep_hours"], 0.03, 4.0, 10.0, 1)
        crew["activity_demo_index"] = int(drift(crew["activity_demo_index"], 5, 5, 95, 0))
        st.session_state.crew_readings.append({
            "timestamp": timestamp,
            "astronaut": astronaut_name,
            "astronaut_id": astronaut_id,
            "source": "Simulated wearable sensor",
            **crew.copy(),
        })

    # Environmental sensors measure the shared spacecraft cabin.
    env = st.session_state.cosmo_environment_values
    env["oxygen_percent"] = drift(env["oxygen_percent"], 0.08, 19.0, 21.5, 2)
    env["co2_ppm"] = drift(env["co2_ppm"], 45, 500, 5000, 0)
    env["temperature_c"] = drift(env["temperature_c"], 0.15, 18, 28, 1)
    env["humidity_percent"] = drift(env["humidity_percent"], 0.8, 25, 65, 1)
    env["pressure_kpa"] = drift(env["pressure_kpa"], 0.12, 95, 105, 2)

    st.session_state.crew_readings = st.session_state.crew_readings[-400:]

if st.session_state.cosmo_sensor_running:
    generate_sensor_snapshot()
    st_autorefresh(interval=3000, limit=None, key="cosmo_sensor_refresh")

st.subheader("Shared spacecraft environment")
st.caption("These readings describe the spacecraft cabin and are common to both astronauts.")
env = st.session_state.cosmo_environment_values
a, b, c, d, e = st.columns(5)
a.metric("Oxygen", f'{env["oxygen_percent"]:.2f} %')
b.metric("Carbon dioxide", f'{env["co2_ppm"]:.0f} ppm')
c.metric("Temperature", f'{env["temperature_c"]:.1f} °C')
d.metric("Humidity", f'{env["humidity_percent"]:.1f} %')
e.metric("Cabin pressure", f'{env["pressure_kpa"]:.2f} kPa')

st.subheader("Cabin sensor status")
sensor_names = [
    "Shared cabin oxygen sensor",
    "Shared cabin CO₂ sensor",
    "Shared cabin temperature sensor",
    "Shared cabin humidity sensor",
    "Shared cabin pressure sensor",
]
status_cols = st.columns(5)
for index, sensor_name in enumerate(sensor_names):
    with status_cols[index]:
        st.caption(f"🟢 Simulated · {sensor_name}")

st.caption(
    "Demonstration only. These shared cabin readings are generated by software, "
    "not physical spacecraft sensors, and are not safety assessments."
)
